"""Package original Aseprite exports in one offline animation inspection page.

This reads image bytes unchanged. All raster authoring is in the adjacent Lua.
"""
from pathlib import Path
import base64
import json

root = Path(__file__).resolve().parent.parent
assets = root / 'public' / 'assets'
bundle = {}
for name in ('characters', 'town', 'objects'):
    bundle[name] = json.loads((assets / f'{name}.json').read_text())
    bundle[name]['imageData'] = 'data:image/png;base64,' + base64.b64encode((assets / f'{name}.png').read_bytes()).decode()
residents = json.loads((assets / 'residents.json').read_text())
scene_data = 'data:image/png;base64,' + base64.b64encode((assets / 'contact-town-populated.png').read_bytes()).decode()
html = r'''<!doctype html>
<html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>GODMODE · Pixel art book</title>
<style>
:root{color-scheme:dark;--ink:#172027;--paper:#e1d6b0;--muted:#a9ad91;--rule:#3b4b50;--gold:#e8b96a}*{box-sizing:border-box}body{margin:0;background:var(--ink);color:var(--paper);font:15px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace}header,main,footer{width:min(1120px,100% - 40px);margin:auto}header{padding:40px 0 22px;border-bottom:1px solid var(--rule)}h1{font:48px/1 Georgia,serif;margin:10px 0}h2{font:28px/1.2 Georgia,serif;font-weight:400}.eyebrow{text-transform:uppercase;letter-spacing:.2em;color:var(--gold);font-size:11px}.intro{max-width:74ch;color:var(--muted)}nav{display:flex;gap:8px;flex-wrap:wrap;margin:25px 0 0}button,select{font:inherit;color:var(--paper);background:#26333b;border:1px solid #566360;padding:8px 13px;border-radius:2px}button{cursor:pointer}button[aria-selected=true]{color:var(--ink);background:var(--paper);border-color:var(--paper)}button:focus-visible,select:focus-visible,a:focus-visible{outline:2px solid var(--gold);outline-offset:4px}main{padding-top:20px}section[hidden]{display:none}.toolbar{display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin:18px 0}label{display:flex;gap:8px;align-items:center;font-size:12px;color:var(--muted)}canvas,img{image-rendering:pixelated}#town-art{display:block;width:800px;max-width:100%;height:auto;border:1px solid var(--rule);margin:20px 0;background:#415136}.caption{font-size:12px;color:var(--muted);max-width:85ch}.roster{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:1px;background:var(--rule);border:1px solid var(--rule);margin-top:20px}.resident{background:#1c292f;padding:20px 10px 14px;text-align:center}.resident canvas{display:block;margin:0 auto 14px}.resident strong{display:block;font:18px Georgia,serif}.resident span{font-size:10px;color:var(--muted)}.inspector{display:flex;gap:30px;align-items:flex-start;flex-wrap:wrap;margin:25px 0}.stage{background:repeating-conic-gradient(#26333b 0% 25%,#303d3e 0% 50%) 50%/16px 16px;padding:28px;min-width:200px;min-height:200px;display:grid;place-items:center;border:1px solid var(--rule)}#detail{max-width:65ch;font-size:12px;white-space:pre-wrap;color:var(--muted)}.links{display:flex;gap:18px;flex-wrap:wrap}a{color:var(--gold)}footer{border-top:1px solid var(--rule);margin-top:45px;padding:24px 0 40px;color:var(--muted);font-size:11px}.palette{display:flex;flex-wrap:wrap;max-width:512px;margin:20px 0}.swatch{width:16px;height:22px}.stats{color:var(--gold);font-size:12px}#frame-key{max-width:min(620px,80vw)}.status{font-size:11px;color:var(--muted)}@media(max-width:600px){h1{font-size:38px}header,main,footer{width:calc(100% - 24px)}.roster{grid-template-columns:repeat(3,1fr)}.resident{padding:14px 2px}.resident strong{font-size:15px}.resident span{font-size:9px}.toolbar{gap:12px}button,select{padding:7px 9px}}
</style>
<header><div class="eyebrow">GODMODE / Original native pixel sources</div><h1>A little town. A lot of heart.</h1><p class="intro">24 named inhabitants. Six action families. Four facings. Big bright eyes, rosy cheeks and one shared chibi rig. These are actual exported game assets, authored locally in Aseprite.</p><p class="stats">1,728 character poses · 576 character animations · 110 town, object and effect source cells</p><nav aria-label="Art book"><button data-tab="scene" aria-selected="true">Town study</button><button data-tab="people" aria-selected="false">24 inhabitants</button><button data-tab="atlas" aria-selected="false">Frame inspector</button></nav></header>
<main>
<section id="scene"><h2>An ordinary afternoon</h2><p class="caption">A source-resolution art staging composition. Characters are placed for readability; this still does not represent a simulated result or an AI decision.</p><img id="town-art" width="400" height="256" alt="Original pixel town with tiled roofs, a bakery oven, well, market, trees, raised footbridge and 24 villagers."><div class="palette" id="palette" aria-label="Shared 64 color palette"></div><p class="caption">16-pixel world grid · 16 × 24-pixel inhabitants · upper-left lighting · nearest-neighbor display. Dry ford, flooded ford, construction and raised bridge cells share geometry and anchors.</p></section>
<section id="people" hidden><h2>Twenty-four persistent faces</h2><div class="toolbar"><label>Action <select id="action"><option>idle</option><option selected>walk</option><option>carry</option><option>talk</option><option>work</option><option>rest</option></select></label><label>Facing <select id="facing"><option value="s">South</option><option value="w">West</option><option value="e">East</option><option value="n">North</option></select></label><label>Scale <select id="scale"><option value="2">2×</option><option value="3" selected>3×</option><option value="4">4×</option></select></label><button id="motion" aria-pressed="false">Pause motion</button></div><p class="caption">Identities use clothing, hair, headwear and role details. Every name has the same 72-pose rig. The small carry basket is neutral; the game can overlay the specific good at cargo anchor (8, 18).</p><div class="roster" id="roster"></div></section>
<section id="atlas" hidden><h2>Inspect the actual cells</h2><div class="toolbar"><label>Sheet <select id="sheet"><option value="town">Town</option><option value="objects">Goods / FX / interface</option><option value="characters">Characters</option></select></label><label>Cell <select id="frame-key"></select></label><label><input id="anchor" type="checkbox" checked> Anchor</label></div><div class="inspector"><div class="stage"><canvas id="inspection"></canvas></div><pre id="detail"></pre></div><p class="caption">Gold cross marks the declared anchor. Frame rectangles include deliberate transparent padding. Interface labels remain real text in the product; no fake text is rasterized into these sheets.</p><div class="links"><a href="characters.png">Characters PNG</a><a href="town.png">Town PNG</a><a href="objects.png">Objects PNG</a><a href="manifest.json">Manifest</a><a href="validation.json">Validation</a></div></section>
<p class="status" id="status" role="status">Loading embedded source images…</p>
</main><footer>Original local Aseprite authoring for GODMODE. No imported game sprites, remote generation job or paid provider call. This page embeds its images and frame metadata, so it also works offline as a single HTML file. Editable masters and reproducible Lua are in the project's art/ folder.</footer>
<script>
const DATA=__BUNDLE__;
const RESIDENTS=__RESIDENTS__;
const SCENE=__SCENE__;
const images={};let active='scene',paused=matchMedia('(prefers-reduced-motion: reduce)').matches,epoch=performance.now();
const $=id=>document.getElementById(id);
$('town-art').src=SCENE;
for(const color of DATA.town.meta.palette){const node=document.createElement('span');node.className='swatch';node.style.background='#'+color;node.title='#'+color;$('palette').append(node)}
for(const r of RESIDENTS){const cell=document.createElement('article');cell.className='resident';const c=document.createElement('canvas');c.width=16;c.height=24;c.dataset.resident=r.id;c.setAttribute('aria-label',r.name+' animation');const n=document.createElement('strong');n.textContent=r.name;const role=document.createElement('span');role.textContent=r.role;cell.append(c,n,role);$('roster').append(cell)}
function resizeRoster(){const n=Number($('scale').value);for(const c of document.querySelectorAll('.resident canvas')){c.style.width=16*n+'px';c.style.height=24*n+'px'}}resizeRoster();$('scale').onchange=resizeRoster;
function motionLabel(){$('motion').textContent=paused?'Play motion':'Pause motion';$('motion').setAttribute('aria-pressed',String(paused))}motionLabel();$('motion').onclick=()=>{paused=!paused;motionLabel()};
document.querySelectorAll('[data-tab]').forEach(button=>button.onclick=()=>{active=button.dataset.tab;document.querySelectorAll('[data-tab]').forEach(b=>b.setAttribute('aria-selected',String(b===button)));for(const id of ['scene','people','atlas'])$(id).hidden=id!==active;});
function drawFrame(ctx,sheet,key,x=0,y=0){const d=DATA[sheet].frames[key];if(!d)return;const f=d.frame;ctx.imageSmoothingEnabled=false;ctx.drawImage(images[sheet],f.x,f.y,f.w,f.h,x,y,f.w,f.h)}
function populateKeys(){const sheet=$('sheet').value;$('frame-key').replaceChildren();for(const key of Object.keys(DATA[sheet].frames)){const o=document.createElement('option');o.value=key;o.textContent=key;$('frame-key').append(o)}inspect()}
function inspect(){if(!images[$('sheet').value])return;const sheet=$('sheet').value,key=$('frame-key').value,d=DATA[sheet].frames[key];if(!d)return;const anchor=d.pixelAnchor;const c=$('inspection');c.width=d.frame.w+12;c.height=d.frame.h+12;c.style.width=c.width*4+'px';c.style.height=c.height*4+'px';const ctx=c.getContext('2d');ctx.clearRect(0,0,c.width,c.height);drawFrame(ctx,sheet,key,6,6);if($('anchor').checked){ctx.strokeStyle='#e8b96a';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(anchor.x+3.5,anchor.y+6.5);ctx.lineTo(anchor.x+9.5,anchor.y+6.5);ctx.moveTo(anchor.x+6.5,anchor.y+3.5);ctx.lineTo(anchor.x+6.5,anchor.y+9.5);ctx.stroke()}$('detail').textContent=key+'\n\n'+JSON.stringify({cell:d.sourceSize,pixelAnchor:d.pixelAnchor,phaserPivot:d.anchor,durationMs:d.duration,rectangle:d.frame},null,2)}
$('sheet').onchange=populateKeys;$('frame-key').onchange=inspect;$('anchor').onchange=inspect;
let heldTime=0,last=0;function tick(t){if(!paused)heldTime+=Math.min(100,t-last);last=t;if(active==='people'){const action=$('action').value,dir=$('facing').value;for(const c of document.querySelectorAll('.resident canvas')){const key=c.dataset.resident+'.'+action+'.'+dir,anim=DATA.characters.animations[key];const index=Math.floor(heldTime/anim.duration)%anim.frames.length;const ctx=c.getContext('2d');ctx.clearRect(0,0,16,24);drawFrame(ctx,'characters',anim.frames[index])}}requestAnimationFrame(tick)}
Promise.all(Object.keys(DATA).map(name=>new Promise((resolve,reject)=>{const image=new Image;image.onload=()=>{images[name]=image;resolve()};image.onerror=reject;image.src=DATA[name].imageData}))).then(()=>{populateKeys();$('status').textContent='All three embedded sheets loaded. Native cells remain unresampled.';requestAnimationFrame(tick)}).catch(()=>{$('status').textContent='An embedded image failed to decode.'});
</script></html>'''
html = html.replace('__BUNDLE__',json.dumps(bundle,separators=(',',':')).replace('<','\\u003c')).replace('__RESIDENTS__',json.dumps(residents,separators=(',',':'))).replace('__SCENE__',json.dumps(scene_data))
(assets/'viewer.html').write_text(html)
print(f'Offline viewer: {len(html):,} bytes')
